import React, { useEffect, useRef, useState } from 'react';
import './App.css';

type CommentNode = {
  id: string;
  text: string;
  deleted: boolean;
  children: CommentNode[];
};

function insertReply(nodes: CommentNode[], parentId: string, reply: CommentNode): CommentNode[] {
  return nodes.map((node) =>
    node.id === parentId
      ? { ...node, children: [...node.children, reply] }
      : { ...node, children: insertReply(node.children, parentId, reply) }
  );
}

function deleteFromTree(nodes: CommentNode[], id: string): CommentNode[] {
  return nodes.flatMap((node) => {
    if (node.id === id) {
      return node.children.length ? [{ ...node, text: '[deleted]', deleted: true }] : [];
    }
    const children = deleteFromTree(node.children, id);
    // A placeholder has nothing left to show once its last reply is gone.
    if (node.deleted && children.length === 0) return [];
    return [{ ...node, children }];
  });
}

function countReplies(node: CommentNode): number {
  return node.children.reduce((total, child) => total + 1 + countReplies(child), 0);
}

function containsComment(node: CommentNode, id: string): boolean {
  return node.children.some((child) => child.id === id || containsComment(child, id));
}

export default function App() {
  const [comments, setComments] = useState<CommentNode[]>([
    { id: '1', text: 'First comment', deleted: false, children: [] }
  ]);
  const [topDraft, setTopDraft] = useState('');
  const [activeReplyId, setActiveReplyId] = useState<string | null>(null);
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [hiddenIds, setHiddenIds] = useState<Record<string, boolean>>({});
  const [threadStatus, setThreadStatus] = useState('');

  const nextIdRef = useRef(2);
  const focusTargetRef = useRef<string | null>(null);
  const makeId = () => String(nextIdRef.current++);

  // The element to focus may only exist after this render, so focus moves here.
  useEffect(() => {
    if (!focusTargetRef.current) return;
    document.getElementById(focusTargetRef.current)?.focus();
    focusTargetRef.current = null;
  });

  const clearDraft = (id: string) => {
    setDrafts((current) => {
      const { [id]: _removed, ...rest } = current;
      return rest;
    });
  };

  const addTop = () => {
    const text = topDraft.trim();
    if (!text) return;
    setComments((current) => [{ id: makeId(), text, deleted: false, children: [] }, ...current]);
    setTopDraft('');
  };

  const openReply = (id: string) => {
    setActiveReplyId(id);
    focusTargetRef.current = `reply-input-${id}`;
  };

  const cancelReply = (id: string) => {
    clearDraft(id);
    setActiveReplyId(null);
    focusTargetRef.current = `reply-button-${id}`;
  };

  const submitReply = (id: string) => {
    const text = (drafts[id] ?? '').trim();
    if (!text) return;
    setComments((current) => insertReply(current, id, { id: makeId(), text, deleted: false, children: [] }));
    setHiddenIds((current) => ({ ...current, [id]: false }));
    clearDraft(id);
    setActiveReplyId(null);
    setThreadStatus('Reply added');
    focusTargetRef.current = `reply-button-${id}`;
  };

  const toggleReplies = (node: CommentNode) => {
    const hide = !hiddenIds[node.id];
    setHiddenIds((current) => ({ ...current, [node.id]: hide }));
    if (hide && activeReplyId && containsComment(node, activeReplyId)) setActiveReplyId(null);
  };

  const deleteComment = (id: string) => {
    setComments((current) => deleteFromTree(current, id));
    clearDraft(id);
    if (activeReplyId === id) setActiveReplyId(null);
    setThreadStatus('Comment deleted');
    focusTargetRef.current = 'comment-box';
  };

  // A plain recursive call on purpose. A component created inside App would get a new
  // identity on every render, and React would rebuild the inputs and lose their focus.
  const renderTree = (nodes: CommentNode[], depth: number) =>
    nodes.map((comment) => {
      const replyCount = countReplies(comment);
      const hidden = !!hiddenIds[comment.id];
      const replyLabel = `Reply to ${comment.text}`;

      return (
        <div key={comment.id} className="node" style={{ marginLeft: depth * 16 }}>
          <div className="bubble">
            <div className="text">{comment.text}</div>
            <div className="meta">
              {!comment.deleted && (
                <button
                  id={`reply-button-${comment.id}`}
                  className="ghost reply-button"
                  aria-label={replyLabel}
                  onClick={() => openReply(comment.id)}
                >
                  Reply
                </button>
              )}
              {replyCount > 0 && (
                <button
                  className="ghost toggle-replies"
                  aria-expanded={!hidden}
                  onClick={() => toggleReplies(comment)}
                >
                  {hidden ? 'Show' : 'Hide'} replies ({replyCount})
                </button>
              )}
              {!comment.deleted && (
                <button
                  className="ghost delete-comment"
                  aria-label={`Delete ${comment.text}`}
                  onClick={() => deleteComment(comment.id)}
                >
                  Delete
                </button>
              )}
            </div>

            {activeReplyId === comment.id && (
              <div className="reply">
                <input
                  id={`reply-input-${comment.id}`}
                  aria-label={replyLabel}
                  value={drafts[comment.id] ?? ''}
                  onChange={(event) => {
                    const value = event.target.value;
                    setDrafts((current) => ({ ...current, [comment.id]: value }));
                  }}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter') {
                      event.preventDefault();
                      submitReply(comment.id);
                    }
                    if (event.key === 'Escape') cancelReply(comment.id);
                  }}
                  placeholder="Write a reply..."
                />
                <div className="replyActions">
                  <button onClick={() => submitReply(comment.id)}>Post</button>
                  <button className="ghost" onClick={() => cancelReply(comment.id)}>Cancel</button>
                </div>
              </div>
            )}
          </div>

          {!hidden && renderTree(comment.children, depth + 1)}
        </div>
      );
    });

  return (
    <main className="page">
      <section className="card">
        <h1 className="title">Nested Comments</h1>
        <p className="subtitle">Replies nest at any depth, long threads can be hidden, and delete keeps other replies.</p>

        <div className="composer">
          <textarea
            id="comment-box"
            rows={3}
            aria-label="Write a comment"
            value={topDraft}
            onChange={(event) => setTopDraft(event.target.value)}
            placeholder="Write a comment..."
          />
          <button onClick={addTop}>Add Comment</button>
        </div>

        <div className="list">{renderTree(comments, 0)}</div>

        <p className="thread-status" aria-live="polite">{threadStatus}</p>
      </section>
    </main>
  );
}

